 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, vec2, vec3, vec4, texture, smoothstep, abs, length, max, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.name = config.id ?? 'badge-pricing';

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const surface = new Color(colors.surface ?? '#0b0b10');
  const accent = new Color(colors.accent ?? '#ff2a38');

  const width = 1.45;
  const height = 0.36;
  const aspect = width / height;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
  });
  const badge = new Mesh(geometry, material);
  group.add(badge);

  const accentStrength = uniform(0.0).label('accentStrength');

  const inkNode = vec3(ink.r, ink.g, ink.b);
  const surfaceNode = vec3(surface.r, surface.g, surface.b);
  const accentNode = vec3(accent.r, accent.g, accent.b);

  const textureUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  let loadedTexture = null;

  const setHover = (on) => {
    gsap.to(group.position, { z: on ? 0.15 : 0, duration: 0.35, ease: 'power2.out' });
    gsap.to(accentStrength, { value: on ? 1.0 : 0.0, duration: 0.25, ease: 'power2.out' });
  };

  const handlers = {
    hover: setHover,
    pointerenter: () => setHover(true),
    pointerleave: () => setHover(false),
    focus: () => setHover(true),
    blur: () => setHover(false),
    pointerdown: () => {
      gsap.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    },
    pointerup: () => {
      gsap.to(group.scale, { x: 1.0, y: 1.0, duration: 0.2, ease: 'power2.out' });
    },
    pointercancel: () => {
      gsap.to(group.scale, { x: 1.0, y: 1.0, duration: 0.2, ease: 'power2.out' });
    },
    click: () => ctx.emit('hub-pricing.select', { id: config.id })
  };

  group.userData.handlers = handlers;
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(accentStrength.value);
    group.remove(badge);
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  ctx.textureLoader.loadTexture(textureUrl).then((tex) => {
    loadedTexture = tex;
    tex.colorSpace = THREE.SRGBColorSpace;

    const mapSample = texture(tex).sample(uv());
    const gray = mapSample.r;

    const u = uv().sub(0.5);
    const q = vec2(u.x.mul(aspect), u.y);
    const flatHalf = aspect / 2 - 0.5;
    const d = length(max(abs(q).sub(vec2(flatHalf, 0)), vec2(0))).sub(0.5);

    const aa = 0.015;
    const fill = smoothstep(0, aa, d).oneMinus();
    const rim = smoothstep(0.04, 0.0, abs(d));

    const base = mix(inkNode, surfaceNode, gray);
    const rimmed = mix(base, accentNode, rim.mul(accentStrength));

    material.colorNode = vec4(rimmed, fill);
    material.needsUpdate = true;
  });

  return group;
}
